const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // 1. Geometry & Time Definitions
  // Define the Antarctic region as a polygon.
  const antarctica = ee.Geometry.Polygon(
      [[[-180, -60], [180, -60], [180, -90], [-180, -90]]], null, false
  );

  // Define the time periods.
  const date2002 = ee.DateRange('2002-09-01', '2002-09-30');
  const date2003 = ee.DateRange('2003-09-01', '2003-09-30');

  // 2. Data Acquisition & Check
  const ozoneCollection = ee.ImageCollection('TOMS/MERGED');

  const col2002 = ozoneCollection.filterDate(date2002).select('ozone');
  const col2003 = ozoneCollection.filterDate(date2003).select('ozone');

  const size2002 = col2002.size().getInfo();
  const size2003 = col2003.size().getInfo();

  if (size2002 === 0 || size2003 === 0) {
    console.log(`Image count for Sep 2002: ${size2002}`);
    console.log(`Image count for Sep 2003: ${size2003}`);
    console.log("No images found for one or both periods.");
    console.log("A"); // C1
    return;
  }
  console.log(`Image count for Sep 2002: ${size2002}`);
  console.log(`Image count for Sep 2003: ${size2003}`);

  // 3. Processing
  // Create a mean composite for each month.
  const mean2002 = col2002.mean();
  const mean2003 = col2003.mean();

  // The ozone hole is defined as the area where ozone levels are < 220 Dobson Units.
  const ozoneHoleThreshold = 220;
  const hole2002 = mean2002.lt(ozoneHoleThreshold);
  const hole2003 = mean2003.lt(ozoneHoleThreshold);

  // Create an image representing the area of each pixel.
  const pixelArea = ee.Image.pixelArea();

  // Calculate the area of the ozone hole for each year.
  const areaImage2002 = hole2002.multiply(pixelArea);
  const areaImage2003 = hole2003.multiply(pixelArea);

  // 4. Calculation
  const scale = 3000; // Use a coarse scale to avoid timeouts over a large area.
  const reduceArgs = {
    reducer: ee.Reducer.sum(),
    geometry: antarctica,
    scale: scale,
    maxPixels: 1e9
  };

  const area2002Result = areaImage2002.reduceRegion(reduceArgs).get('ozone');
  const area2003Result = areaImage2003.reduceRegion(reduceArgs).get('ozone');

  // Request results from the server.
  const area2002 = area2002Result.getInfo();
  const area2003 = area2003Result.getInfo();

  // 5. Validation & Final Answer
  if (area2002 === null || area2003 === null) {
      console.log("Failed to calculate ozone hole area for one or both years.");
      console.log(`Area 2002: ${area2002}`);
      console.log(`Area 2003: ${area2003}`);
      console.log("C3");
      return;
  }

  // Convert area from square meters to million square kilometers for readability.
  const area2002_M_km2 = area2002 / 1e12;
  const area2003_M_km2 = area2003 / 1e12;

  console.log(`Avg. ozone hole size Sep 2002: ${area2002_M_km2.toFixed(2)} million km^2`);
  console.log(`Avg. ozone hole size Sep 2003: ${area2003_M_km2.toFixed(2)} million km^2`);

  if (area2003 > area2002) {
    console.log("The ozone hole size increased in Sep 2003 compared to Sep 2002.");
    console.log("A");
  } else {
    console.log("The ozone hole size did not increase in Sep 2003 compared to Sep 2002.");
    console.log("B");
  }
}

async function initEE() {
  try {
    await new Promise((resolve, reject) => {
      ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
    });
    await new Promise((resolve, reject) => {
      ee.initialize(null, null, resolve, reject);
    });
    await runAnalysis();
  } catch (e) {
    console.error(`An error occurred: ${e}`);
    console.log("D");
  }
}

initEE();
